package com.bank.validate;

import java.math.BigDecimal;

class TransferValidator {

    // SAFE: short-circuit && skips the right operand when account is null.
    boolean canTransferSafe(Account account, BigDecimal amount) {
        return account != null && account.getBalance().compareTo(amount) >= 0;
    }

    // BUGGY: single & ALWAYS evaluates the right operand → NPE when null.
    boolean canTransferBuggy(Account account, BigDecimal amount) {
        return account != null & account.getBalance().compareTo(amount) >= 0; // DON'T
    }
}
