package com.bank.validate;

// Correct, intended use of bitwise & and | on INTEGERS for account flags.
class FeatureFlags {
    static final int UPI_ENABLED      = 1;      // bit 0
    static final int INTL_TRANSFER    = 1 << 1; // bit 1
    static final int OVERDRAFT        = 1 << 2; // bit 2

    // Combine flags with bitwise OR.
    int enable(int current, int flag) { return current | flag; }

    // Test a flag with bitwise AND.
    boolean isEnabled(int current, int flag) { return (current & flag) != 0; }
}
