package com.bank.validate;

import java.math.BigDecimal;
import java.util.logging.*;

public class OperatorDemo {
    private static final Logger log = Logger.getLogger(OperatorDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        TransferValidator validator = new TransferValidator();

        Account rajesh = new Account("SAV2001", new BigDecimal("1000000"));
        Account closed = null; // lookup returned null for a closed account

        // 1) SAFE short-circuit guard: null account → false, no exception.
        log.info(() -> "Safe guard, valid account: " + validator.canTransferSafe(rajesh, new BigDecimal("50000")));
        log.info(() -> "Safe guard, null account: " + validator.canTransferSafe(closed, new BigDecimal("50000"))
                + " (short-circuit skipped the dereference)");

        // 2) BUGGY non-short-circuit guard: null account → NPE.
        try {
            boolean ok = validator.canTransferBuggy(closed, new BigDecimal("50000"));
            log.info(() -> "unexpected " + ok);
        } catch (NullPointerException e) {
            log.log(Level.SEVERE, "Single & evaluated right operand on null account", e);
        }

        // 3) Short-circuit || skips the expensive secondary check.
        boolean fraud = cheapCheckFails() || expensiveCheckFails();
        log.info(() -> "Fraud (||): " + fraud + " (expensive check only if cheap failed)");

        // 4) Correct bitwise use on integers for feature flags.
        FeatureFlags flags = new FeatureFlags();
        int acct = 0;
        acct = flags.enable(acct, FeatureFlags.UPI_ENABLED);
        acct = flags.enable(acct, FeatureFlags.OVERDRAFT);
        final int finalAcct = acct;
        log.info(() -> "UPI enabled? " + flags.isEnabled(finalAcct, FeatureFlags.UPI_ENABLED));
        log.info(() -> "Intl transfer enabled? " + flags.isEnabled(finalAcct, FeatureFlags.INTL_TRANSFER));
        log.info(() -> "Flags bits = " + Integer.toBinaryString(finalAcct));
    }

    private static boolean cheapCheckFails() { return false; }  // passes → false
    private static boolean expensiveCheckFails() {
        Logger.getLogger(OperatorDemo.class.getName()).warning("expensive check RAN");
        return true;
    }
}

